CREATE TEMPORARY VIEW dwd_view_metric_${grass_region_without_quote} AS
SELECT
    user_id
    ,local_date
FROM
    srdi_mart.dws_sr_data_warehouse_search_srp_user_benchmark_1d
WHERE
