--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_search_uu_metrics_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,COUNT(DISTINCT IF(DATE_SUB(${local_date}, 14) <= a.local_date AND a.local_date <= ${local_date}, a.user_id, NULL)) AS search_uu_14d
    ,COUNT(DISTINCT a.user_id) AS search_uu_30d
FROM
    user_exp_mapping_${grass_region_without_quote} a
JOIN
    dwd_view_metric_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
    AND a.local_date = b.local_date
GROUP BY
