--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_order_metrics_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,SUM(IF(DATE_SUB(${local_date}, 14) <= a.local_date AND a.local_date <= ${local_date}, order_cnt, NULL)) AS order_cnt_14d
    ,COUNT(DISTINCT IF(DATE_SUB(${local_date}, 14) <= a.local_date AND a.local_date <= ${local_date} AND order_cnt > 0, a.user_id, NULL)) AS order_uu_14d
    ,SUM(IF(DATE_SUB(${local_date}, 14) <= a.local_date AND a.local_date <= ${local_date}, gmv, NULL)) AS gmv_14d
    ,SUM(order_cnt) AS order_cnt_30d
    ,COUNT(DISTINCT IF(order_cnt > 0, a.user_id, NULL)) AS order_uu_30d
    ,SUM(gmv) AS gmv_30d
FROM
    user_exp_mapping_${grass_region_without_quote} a
JOIN
    dwm_order_metrics_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
    AND a.local_date = b.local_date
GROUP BY
    1;

